solution.exercise.c:
#include "exercise.h"
#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
bool parse_decimal(const char *s, uint64_t *out) {
    uint64_t n = 0;
    for (; *s; s++) {
        int d = isdigit((unsigned char)*s)
                    ? *s - '0'
                    : (tolower((unsigned char)*s) >= 'a' &&
                               tolower((unsigned char)*s) <= 'f'
                           ? tolower((unsigned char)*s) - 'a' + 10
                           : 99);
        if (d >= 16 || n > (UINT64_MAX - (unsigned)d) / 16)
            return false;
        n = n * 16 + d;
    }
    *out = n;
    return true;
}
uint64_t to_decimal(const char *s) {
    uint64_t n = 0;
    parse_decimal(s, &n);
    return n;
}

tests.test_exercise.c:
#include "exercise.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool positive(int x) { return x > 0; }
static bool bstring(const void *p) { return (*(const char *const *)p)[0] == 98; }
static void string_length(const void *p, void *out) {
    *(size_t *)out = strlen(*(const char *const *)p);
}

int main(void) {
    assert(to_decimal("10") == 16);
    assert(to_decimal("1") == 1);
    assert(to_decimal("") == 0);
    assert(to_decimal("xyz") == 0);
    uint64_t parsed;
    assert(!parse_decimal("xyz", &parsed));
    assert(parse_decimal("10", &parsed) && parsed == 16);
    assert(to_decimal("ff") == 255);
    assert(to_decimal("1") == 1);
    assert(to_decimal("c") == 12);
    assert(to_decimal("10") == 16);
    assert(to_decimal("af") == 175);
    assert(to_decimal("100") == 256);
    assert(to_decimal("19ACE") == 105166);
    assert(to_decimal("000000") == 0);
    assert(to_decimal("ffff00") == 16776960);
    assert(to_decimal("00fff0") == 65520);
    return 0;
}
